"use client";

import { BRAND_NAME, LOGO_SRC } from "@/components/ui/Logo";

export interface PrintableQr {
  size: number;
  path: string;
  title: string;
  /** Highlighted clinical detail shown inside the QR block, e.g. "Recommendation given: ...". */
  detail?: string;
  hint: string;
}

export interface PrintablePainDiagram {
  /** Self-contained inline SVG markup generated by buildPainAreaDiagramSvg. */
  svg: string;
  heading: string;
  primaryLocation: string;
  secondaryLocation?: string;
}

export interface PrintableSummary {
  lang: string;
  /** Line under the title, e.g. "Pentru medic · 8 noiembrie 2026". */
  meta: string;
  title: string;
  rows: { label: string; value: string }[];
  notes: string[];
  /** Emergency / no-emergency line; shown in red when `urgent`. */
  status: string;
  urgent: boolean;
  /** Visual anatomical diagram pinpointing where it hurts on Front + Back views. */
  painDiagram?: PrintablePainDiagram;
  /** Clinical QR handoff block rendered as crisp vector SVG on the PDF sheet. */
  qr?: PrintableQr;
  /** Footer line, e.g. the disclaimer. */
  footer?: string;
  /** Used by "Save as PDF" as the file name. */
  fileName: string;
}

const escape = (value: string) =>
  value.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c] ?? c);

/**
 * Builds the standalone A4 clinical PDF HTML document, including the anatomical pain diagram and vector SVG QR block.
 */
export function buildPrintSummaryHtml(summary: PrintableSummary, logoUrl: string): string {
  const rows = summary.rows
    .map((r) => `<div class="row"><dt>${escape(r.label)}</dt><dd>${escape(r.value)}</dd></div>`)
    .join("");
  const notes = summary.notes.map((n) => `<p class="note">${escape(n)}</p>`).join("");
  const painMarkup =
    summary.painDiagram && summary.painDiagram.svg
      ? `<aside class="pain-map">
          <p class="pain-map-heading">${escape(summary.painDiagram.heading)}</p>
          <div class="pain-map-figure">${summary.painDiagram.svg}</div>
          <p class="pain-map-primary">${escape(summary.painDiagram.primaryLocation)}</p>
          ${summary.painDiagram.secondaryLocation ? `<p class="pain-map-secondary">${escape(summary.painDiagram.secondaryLocation)}</p>` : ""}
        </aside>`
      : "";
  const bodySectionMarkup = painMarkup
    ? `<div class="clinical-grid"><dl>${rows}</dl>${painMarkup}</div>`
    : `<dl>${rows}</dl>`;
  const qrSize = summary.qr && Number.isFinite(summary.qr.size) && summary.qr.size > 0 ? summary.qr.size : 0;
  const qrMarkup =
    summary.qr && qrSize > 0 && summary.qr.path
      ? `<div class="qr-handoff">
          <div class="qr-frame">
            <svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 ${qrSize} ${qrSize}" shape-rendering="crispEdges" role="img" aria-label="${escape(summary.qr.title)}">
              <rect width="${qrSize}" height="${qrSize}" fill="#ffffff" />
              <path d="${escape(summary.qr.path)}" fill="#0b132b" />
            </svg>
          </div>
          <div class="qr-copy">
            <p class="qr-title">${escape(summary.qr.title)}</p>
            ${summary.qr.detail ? `<p class="qr-detail">${escape(summary.qr.detail)}</p>` : ""}
            <p class="qr-hint">${escape(summary.qr.hint)}</p>
          </div>
        </div>`
      : "";

  return `<!doctype html>
<html lang="${escape(summary.lang)}">
<head>
<meta charset="utf-8">
<title>${escape(summary.fileName)}</title>
<style>
  /* Zero page margin hides the browser's own date / URL / page-number lines; spacing lives on body. */
  @page { size: A4; margin: 0; }
  :root { color-scheme: light; }
  * { box-sizing: border-box; }
  html { background: #fff; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  body { margin: 0; padding: 13mm 15mm; background: #fff; color: #0b132b; font: 11pt/1.45 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
  header { display: flex; align-items: center; gap: 10px; padding-bottom: 10px; border-bottom: 1.5px solid #0b132b; }
  header img { width: 28px; height: 28px; }
  header span { font-size: 14pt; font-weight: 600; letter-spacing: -0.01em; }
  h1 { margin: 14px 0 2px; font-size: 18.5pt; line-height: 1.2; }
  .meta { margin: 0 0 12px; color: #475569; font-size: 9.75pt; }
  .clinical-grid { display: grid; grid-template-columns: 1fr 196px; gap: 16px; align-items: start; }
  dl { margin: 0; border-top: 1px solid #e2e8f0; min-width: 0; }
  .row { display: grid; grid-template-columns: 36% 1fr; gap: 10px; padding: 7px 0; border-bottom: 1px solid #e2e8f0; break-inside: avoid; page-break-inside: avoid; }
  dt { color: #475569; font-size: 9.75pt; }
  dd { margin: 0; font-weight: 600; overflow-wrap: break-word; }
  .pain-map { padding: 10px; border: 1px solid #cbd5e1; border-radius: 8px; background: #f8fafc; break-inside: avoid; page-break-inside: avoid; }
  .pain-map-heading { margin: 0 0 6px; font-size: 9pt; font-weight: 700; color: #334155; }
  .pain-map-figure svg { display: block; width: 100%; height: auto; }
  .pain-map-primary { margin: 6px 0 0; font-size: 9.75pt; font-weight: 700; color: #0b132b; line-height: 1.3; overflow-wrap: break-word; }
  .pain-map-secondary { margin: 2px 0 0; font-size: 8.75pt; font-weight: 500; color: #475569; line-height: 1.3; overflow-wrap: break-word; }
  .note { margin: 10px 0 0; }
  .status { margin: 11px 0 0; font-weight: 600; color: #475569; }
  .status.urgent { color: #c62f3c; }
  .qr-handoff { display: flex; align-items: center; gap: 14px; margin-top: 14px; padding: 10px 12px; border: 1px solid #cbd5e1; border-radius: 8px; break-inside: avoid; page-break-inside: avoid; }
  .qr-frame { flex-shrink: 0; padding: 4px; border: 1px solid #e2e8f0; border-radius: 6px; background: #fff; line-height: 0; }
  .qr-frame svg { display: block; width: 96px; height: 96px; }
  .qr-copy { min-width: 0; }
  .qr-title { margin: 0; font-size: 10.25pt; font-weight: 600; color: #0b132b; }
  .qr-detail { margin: 4px 0 0; padding: 4px 8px; border-left: 2.5px solid #1d4ed8; background: #f1f5f9; font-size: 9.75pt; font-weight: 700; color: #0b132b; line-height: 1.35; overflow-wrap: break-word; }
  .qr-hint { margin: 4px 0 0; font-size: 9pt; line-height: 1.38; color: #475569; }
  footer { margin-top: 14px; padding-top: 9px; border-top: 1px solid #e2e8f0; color: #475569; font-size: 9pt; }
</style>
</head>
<body>
  <header><img src="${escape(logoUrl)}" alt=""><span>${escape(BRAND_NAME)}</span></header>
  <h1>${escape(summary.title)}</h1>
  <p class="meta">${escape(summary.meta)}</p>
  ${bodySectionMarkup}
  ${notes}
  <p class="status${summary.urgent ? " urgent" : ""}">${escape(summary.status)}</p>
  ${qrMarkup}
  ${summary.footer ? `<footer>${escape(summary.footer)}</footer>` : ""}
</body>
</html>`;
}

/**
 * Prints the doctor summary as its own clean A4 document (with the site logo and vector QR code)
 * instead of the live page, so the PDF never depends on overlays, scroll position or page styles.
 */
export function printSummary(summary: PrintableSummary) {
  const frame = document.createElement("iframe");
  frame.setAttribute("aria-hidden", "true");
  frame.style.cssText = "position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden";
  document.body.appendChild(frame);

  const doc = frame.contentDocument;
  const win = frame.contentWindow;
  if (!doc || !win) {
    frame.remove();
    return;
  }

  const logoUrl = new URL(LOGO_SRC, window.location.origin).href;
  doc.open();
  doc.write(buildPrintSummaryHtml(summary, logoUrl));
  doc.close();

  const cleanup = () => setTimeout(() => frame.remove(), 500);
  const run = () => {
    win.addEventListener("afterprint", cleanup, { once: true });
    win.focus();
    win.print();
    // Some browsers never fire afterprint for iframes; remove the frame anyway.
    setTimeout(() => frame.isConnected && frame.remove(), 60_000);
  };

  // Print once the logo has loaded (or failed), so it is on the page.
  const img = doc.querySelector("img");
  if (img && !img.complete) {
    img.addEventListener("load", run, { once: true });
    img.addEventListener("error", run, { once: true });
  } else {
    run();
  }
}
